-- Reviewed local synthetic members and a ready owned main reference only.
-- Every provider receipt below is explicitly synthetic and transaction-local;
-- this fixture performs no HTTP, upload, generation, publishing or wallet RPC.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE native_bridge_fixture_results(name text PRIMARY KEY,passed boolean NOT NULL);
CREATE FUNCTION pg_temp.bridge_assert(p boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF p IS NOT TRUE THEN RAISE EXCEPTION 'FIXTURE_ASSERTION_FAILED: %',label;END IF;INSERT INTO native_bridge_fixture_results VALUES(label,true);END$$;
CREATE FUNCTION pg_temp.bridge_record_v3(p_owner text,p_bridge uuid,p_phase text,p_dispatch uuid,p_asset uuid) RETURNS jsonb LANGUAGE plpgsql AS $$DECLARE b public.pub_native_media_bridges%ROWTYPE;phase public.pub_native_media_bridge_phases%ROWTYPE;v3 jsonb;result jsonb;op jsonb;BEGIN
 SELECT * INTO b FROM public.pub_native_media_bridges WHERE id=p_bridge AND owner_id=p_owner;SELECT ph.* INTO phase FROM public.pub_native_media_bridge_phases ph WHERE ph.bridge_id=p_bridge AND ph.owner_id=p_owner AND ph.phase=p_phase;
 v3:=jsonb_build_object('action',CASE p_phase WHEN 'sign' THEN 'prepare-upload' ELSE 'prepare-confirm' END,'connectionId',b.namespace,'operationId',gen_random_uuid(),'requestKey',phase.operation_request_key,'requestHash',repeat('a',64),'providerRequestHash',repeat('b',64));
 IF p_phase='sign' THEN v3:=v3||jsonb_build_object('assetId',p_asset,'asset',jsonb_build_object('mediaId',b.media_id,'fileName',b.snapshot->'file'->'fileName','mime',b.snapshot->'file'->'mime','size',b.snapshot->'file'->'size','sha256',b.snapshot->'file'->'sha256'),'snapshot',jsonb_build_object('request',jsonb_build_object('filename',b.snapshot->'file'->'fileName','size',b.snapshot->'file'->'size','type','publishMedia')));
 ELSE v3:=v3||jsonb_build_object('assetId',p_asset,'snapshot',jsonb_build_object('request',jsonb_build_object('assetId',phase.provider_asset_id)));END IF;
 result:=public.mutate_native_media_bridge_atomic(p_owner,jsonb_build_object('action','prepare-v3','requestKey','native-bridge:'||p_bridge::text||':prepare-v3:'||p_phase,'currentNamespace',b.namespace,'bridgeId',b.id,'phase',p_phase,'dispatchId',p_dispatch,'input',v3));op:=result->'operation';
 result:=public.mutate_publish_v3_atomic(p_owner,jsonb_build_object('action','dispatch','connectionId',b.namespace,'operationId',op->'id'));IF result->'shouldSend' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'FIXTURE_FIRST_V3_DISPATCH_REQUIRED';END IF;
 result:=public.mutate_publish_v3_atomic(p_owner,jsonb_build_object('action','consume-grant','connectionId',b.namespace,'operationId',op->'id','grantKind',op->'grant_kind','grantSubject',op->'grant_subject','providerRequestHash',op->'provider_request_hash'));IF result->'consumed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'FIXTURE_FIRST_V3_GRANT_REQUIRED';END IF;
 RETURN public.mutate_publish_v3_atomic(p_owner,jsonb_build_object('action','record-asset','connectionId',b.namespace,'operationId',op->'id','providerAssetId','synthetic.'||p_bridge::text,'publicUrl','https://example.org/synthetic-bridge/'||p_bridge::text,'size',b.snapshot->'file'->'size','mime',b.snapshot->'file'->'mime','metadata',jsonb_build_object('duration',1)));
END$$;
DO $$<<fixture>>DECLARE
 actor text:=current_setting('native_ai.fixture_owner',true);other_actor text:=current_setting('native_ai.fixture_other_owner',true);reference jsonb:=current_setting('native_media.fixture_reference',true)::jsonb;
 bridge_id uuid:=gen_random_uuid();media_id uuid:=gen_random_uuid();asset_id uuid:=gen_random_uuid();namespace text;prefix text;snapshot jsonb;request jsonb;claim jsonb;sign_dispatch uuid;put_dispatch uuid;confirm_dispatch uuid;result jsonb;evidence jsonb;rejected boolean;before_wallet jsonb;fake_v3 jsonb;metadata jsonb;source jsonb;collection uuid;draft uuid;entry_id uuid;payload jsonb;binding_id uuid:=gen_random_uuid();auth_id uuid:=gen_random_uuid();intent jsonb;facts jsonb;proof jsonb;other_bridge uuid:=gen_random_uuid();other_media uuid:=gen_random_uuid();other_asset uuid:=gen_random_uuid();other_snapshot jsonb;
BEGIN
 IF actor IS NULL OR other_actor IS NULL OR actor=other_actor OR reference IS NULL THEN RAISE EXCEPTION 'EXPLICIT_SYNTHETIC_BRIDGE_OWNERS_AND_READY_SOURCE_REQUIRED';END IF;
 PERFORM public.pub_assert_actor(actor);PERFORM public.pub_assert_actor(other_actor);namespace:='fixture:bridge:'||bridge_id::text;prefix:='native-bridge:'||bridge_id::text;
 SELECT jsonb_build_object('credits',credits,'cash',cash_balance) INTO before_wallet FROM public.users WHERE id=actor;
 evidence:=public.read_native_media_bridge_atomic(actor,jsonb_build_object('action','source-evidence','reference',reference));
 PERFORM pg_temp.bridge_assert(evidence?&ARRAY['sourceFingerprint'] AND length(evidence->>'sourceFingerprint')=64 AND (SELECT count(*) FROM jsonb_object_keys(evidence))=1,'source evidence exports only PG digest and no locator');
 snapshot:=jsonb_build_object('version',1,'reference',reference,'mediaId',media_id,'namespace',namespace,'sourceFingerprint',evidence->'sourceFingerprint','file',jsonb_build_object('fileName','native-bridge-'||bridge_id::text||CASE WHEN reference->>'kind'='video_task' THEN '.mp4' ELSE '.png' END,'mime',CASE WHEN reference->>'kind'='video_task' THEN 'video/mp4' ELSE 'image/png' END,'size',16,'sha256',repeat('c',64)));
 request:=jsonb_build_object('action','prepare','requestKey','bridge.fixture.prepare.'||bridge_id::text,'currentNamespace',namespace,'bridgeId',bridge_id,'snapshot',snapshot,'snapshotHash',repeat('d',64));
 rejected:=false;BEGIN PERFORM public.mutate_native_media_bridge_atomic(actor,jsonb_set(request,'{snapshot,sourceFingerprint}',to_jsonb(repeat('e',64))));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_SOURCE_CHANGED';END;PERFORM pg_temp.bridge_assert(rejected,'prepare rejects stale or client-invented source fingerprint');
 result:=public.mutate_native_media_bridge_atomic(actor,request);
 PERFORM pg_temp.bridge_assert(result->'bridge'->>'state'='prepared' AND result->'bridge'->'resultReference'='null'::jsonb AND NOT(result->'bridge'?'namespace') AND NOT(result->'bridge'?'snapshot') AND NOT(result->'bridge'?'providerAssetId'),'prepared DTO exposes no internal namespace source locator or remote provider identity');
 result:=public.read_native_media_bridge_atomic(actor,jsonb_build_object('action','invocation','bridgeId',bridge_id,'phase','confirm','dispatchId',NULL,'currentNamespace',namespace));PERFORM pg_temp.bridge_assert(result->'phase'->>'state'='pending' AND result->'phase'->'dispatchId'='null'::jsonb AND NOT(result?'shouldDispatch'),'null invocation only reads genuinely unclaimed pending phase without permit');
 result:=public.mutate_native_media_bridge_atomic(actor,request);PERFORM pg_temp.bridge_assert(result->'alreadyFulfilled'='true'::jsonb AND (SELECT count(*) FROM public.pub_native_media_bridges WHERE id=bridge_id)=1,'same-key prepared replay does not create another reservation');
 rejected:=false;BEGIN PERFORM public.mutate_native_media_bridge_atomic(actor,jsonb_set(request,'{snapshot,file,size}','17'));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='PUBLISH_IDEMPOTENCY_CONFLICT';END;PERFORM pg_temp.bridge_assert(rejected,'same prepare key cannot replace immutable bytes');
 result:=public.read_native_media_bridge_atomic(other_actor,jsonb_build_object('action','bridge','bridgeId',bridge_id,'currentNamespace',namespace));PERFORM pg_temp.bridge_assert(result='{"found":false}'::jsonb,'foreign owner cannot look up bridge');
 rejected:=false;BEGIN PERFORM public.read_native_media_bridge_atomic(other_actor,jsonb_build_object('action','source-evidence','reference',reference));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='PUBLISH_V2_ASSET_UNAVAILABLE';END;PERFORM pg_temp.bridge_assert(rejected,'foreign owner cannot obtain source evidence');
 claim:=jsonb_build_object('action','claim-phase','requestKey',prefix||':claim:sign','currentNamespace',namespace,'bridgeId',bridge_id,'expectedRevision',1,'phase','sign');result:=public.mutate_native_media_bridge_atomic(actor,claim);sign_dispatch:=(result->'phase'->>'dispatchId')::uuid;
 PERFORM pg_temp.bridge_assert(result->'shouldDispatch'='true'::jsonb AND sign_dispatch IS NOT NULL,'prepared explicit continuation gets exactly one first sign phase grant');
 result:=public.mutate_native_media_bridge_atomic(actor,claim);PERFORM pg_temp.bridge_assert(result->'shouldDispatch'='false'::jsonb AND result->'phase'->>'dispatchId'=sign_dispatch::text,'sign phase replay never grants another dispatch');
 rejected:=false;BEGIN PERFORM public.read_native_media_bridge_atomic(actor,jsonb_build_object('action','invocation','bridgeId',bridge_id,'phase','sign','dispatchId',NULL,'currentNamespace',namespace));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_PHASE_INVALID';END;PERFORM pg_temp.bridge_assert(rejected,'null invocation cannot recover an already claimed grant');
 fake_v3:=jsonb_build_object('action','prepare-upload','connectionId',namespace,'operationId',gen_random_uuid(),'assetId',asset_id,'requestKey',prefix||':sign','requestHash',repeat('a',64),'providerRequestHash',repeat('b',64),'asset',jsonb_build_object('mediaId',media_id,'fileName',snapshot->'file'->'fileName','mime',snapshot->'file'->'mime','size',snapshot->'file'->'size','sha256',snapshot->'file'->'sha256'),'snapshot',jsonb_build_object('request',jsonb_build_object('filename',snapshot->'file'->'fileName','size',snapshot->'file'->'size','type','publishMedia')));
 rejected:=false;BEGIN PERFORM public.mutate_publish_v3_atomic(actor,fake_v3);EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_MEDIA_RESERVED';END;PERFORM pg_temp.bridge_assert(rejected,'ordinary V3 sign cannot use reserved main media even with stable guessed key');
 rejected:=false;BEGIN PERFORM public.mutate_publish_v3_atomic(actor,jsonb_set(fake_v3,'{asset,mediaId}',to_jsonb(gen_random_uuid())));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_MEDIA_RESERVED';END;PERFORM pg_temp.bridge_assert(rejected,'reserved filename prefix cannot be resigned under a different media id');
 result:=pg_temp.bridge_record_v3(actor,bridge_id,'sign',sign_dispatch,asset_id);
 result:=public.mutate_native_media_bridge_atomic(actor,jsonb_build_object('action','reconcile','requestKey',prefix||':reconcile:sign','currentNamespace',namespace,'bridgeId',bridge_id));
 PERFORM pg_temp.bridge_assert(result->'bridge'->>'state'='uploading' AND (SELECT ph.state='recorded' AND ph.asset_id=fixture.asset_id FROM public.pub_native_media_bridge_phases ph WHERE ph.bridge_id=fixture.bridge_id AND ph.phase='sign'),'sign reconciles only its exact settled grant-used V3 receipt');
 rejected:=false;BEGIN PERFORM public.mutate_publish_v3_atomic(actor,jsonb_build_object('action','prepare-confirm','connectionId',namespace,'operationId',gen_random_uuid(),'assetId',asset_id,'requestKey',prefix||':confirm','requestHash',repeat('a',64),'providerRequestHash',repeat('b',64),'snapshot',jsonb_build_object('request',jsonb_build_object('assetId','synthetic.'||bridge_id::text))));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_MEDIA_RESERVED';END;PERFORM pg_temp.bridge_assert(rejected,'ordinary V3 confirm cannot bypass reserved bridge phase');
 result:=public.read_native_media_bridge_atomic(actor,jsonb_build_object('action','bridge','bridgeId',bridge_id,'currentNamespace',namespace));
 rejected:=false;BEGIN PERFORM public.mutate_native_media_bridge_atomic(actor,jsonb_build_object('action','claim-phase','requestKey',prefix||':claim:confirm','currentNamespace',namespace,'bridgeId',bridge_id,'expectedRevision',result->'bridge'->'revision','phase','confirm'));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_PHASE_INVALID';END;PERFORM pg_temp.bridge_assert(rejected,'confirmation cannot claim before exact PUT acknowledgement');
 result:=public.mutate_native_media_bridge_atomic(actor,jsonb_build_object('action','claim-phase','requestKey',prefix||':claim:put','currentNamespace',namespace,'bridgeId',bridge_id,'expectedRevision',result->'bridge'->'revision','phase','put'));put_dispatch:=(result->'phase'->>'dispatchId')::uuid;
 PERFORM pg_temp.bridge_assert(result->'shouldDispatch'='true'::jsonb AND result->'phase'->>'assetId'=asset_id::text AND result->'phase'->>'providerAssetId'='synthetic.'||bridge_id::text,'PUT phase carries exact sign asset identity');
 proof:=jsonb_build_object('httpStatus',200,'sha256',snapshot->'file'->'sha256','size',snapshot->'file'->'size','mime',snapshot->'file'->'mime');
 rejected:=false;BEGIN PERFORM public.mutate_native_media_bridge_atomic(actor,jsonb_build_object('action','record-put','requestKey',prefix||':put-receipt','currentNamespace',namespace,'bridgeId',bridge_id,'dispatchId',put_dispatch,'proof',jsonb_set(proof,'{sha256}',to_jsonb(repeat('f',64)))));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_PUT_PROOF_INVALID';END;PERFORM pg_temp.bridge_assert(rejected,'PUT acknowledgement cannot replace exact server byte proof');
 result:=public.mutate_native_media_bridge_atomic(actor,jsonb_build_object('action','record-put','requestKey',prefix||':put-receipt','currentNamespace','rotated:namespace','bridgeId',bridge_id,'dispatchId',put_dispatch,'proof',proof));
 PERFORM pg_temp.bridge_assert(result->'bridge'->'connectionCurrent'='false'::jsonb AND (SELECT ph.state='recorded' FROM public.pub_native_media_bridge_phases ph WHERE ph.bridge_id=fixture.bridge_id AND ph.phase='put'),'real original PUT receipt survives namespace rotation without new dispatch permission');
 rejected:=false;BEGIN PERFORM public.mutate_native_media_bridge_atomic(actor,jsonb_build_object('action','claim-phase','requestKey',prefix||':claim:confirm','currentNamespace','rotated:namespace','bridgeId',bridge_id,'expectedRevision',result->'bridge'->'revision','phase','confirm'));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_NAMESPACE_CHANGED';END;PERFORM pg_temp.bridge_assert(rejected,'rotated namespace cannot claim new confirmation');
 result:=public.mutate_native_media_bridge_atomic(actor,jsonb_build_object('action','claim-phase','requestKey',prefix||':claim:confirm','currentNamespace',namespace,'bridgeId',bridge_id,'expectedRevision',result->'bridge'->'revision','phase','confirm'));confirm_dispatch:=(result->'phase'->>'dispatchId')::uuid;
 result:=pg_temp.bridge_record_v3(actor,bridge_id,'confirm',confirm_dispatch,asset_id);
 result:=public.mutate_native_media_bridge_atomic(actor,jsonb_build_object('action','reconcile','requestKey',prefix||':reconcile:ready','currentNamespace',namespace,'bridgeId',bridge_id));
 PERFORM pg_temp.bridge_assert(result->'bridge'->>'state'='ready' AND result->'bridge'->'resultReference'=jsonb_build_object('kind','provider_asset','assetId',asset_id,'mediaId',media_id) AND (SELECT count(*)=3 AND bool_and(ph.state='recorded') FROM public.pub_native_media_bridge_phases ph WHERE ph.bridge_id=fixture.bridge_id),'ready requires recorded sign PUT and confirm and returns local provider UUID');
 PERFORM pg_temp.bridge_assert((SELECT hash_source='browser_declared' FROM public.pub3_assets WHERE id=asset_id),'bridge does not falsely upgrade provider hash verification');
 source:=jsonb_build_object('kind','main_asset','reference',reference);metadata:=jsonb_build_object('schemaVersion',2,'media',jsonb_build_array(jsonb_build_object('mediaId',media_id,'source',source)),'coverMediaId',NULL,'accountTypes','[]'::jsonb,'maxUseCountByAccountType','{}'::jsonb);
 PERFORM public.native_media_bridge_assert_targets(actor,namespace,metadata,jsonb_build_array(media_id),NULL,jsonb_build_array(asset_id));
 rejected:=false;BEGIN PERFORM public.native_media_bridge_assert_targets(actor,'rotated:namespace',metadata,jsonb_build_array(media_id),NULL,jsonb_build_array(asset_id));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_MAIN_BRIDGE_REQUIRED';END;PERFORM pg_temp.bridge_assert(rejected,'ready bridge cannot authorize another namespace');
 PERFORM public.native_media_bridge_assert_targets(actor,namespace,metadata,'[]'::jsonb,to_jsonb(media_id),jsonb_build_array(asset_id));
 proof:=jsonb_build_object('id',asset_id,'mediaId',media_id,'sha256',snapshot->'file'->'sha256','size',snapshot->'file'->'size','mime',snapshot->'file'->'mime');
 PERFORM pg_temp.bridge_assert(public.native_media_bridge_proven(actor,namespace,reference,media_id,proof) AND NOT public.native_media_bridge_proven(actor,namespace,reference,media_id,jsonb_set(proof,'{sha256}',to_jsonb(repeat('f',64)))),'historical official attribution requires exact local asset and byte facts');
 result:=public.mutate_publish_v2_atomic(actor,jsonb_build_object('action','save-collection','expectedRevision',0,'name','bridge source fixture','description','','archived',false));collection:=(result->'row'->>'id')::uuid;
 payload:=jsonb_build_object('schemaVersion',2,'collectionId',collection,'contentType',CASE WHEN reference->>'kind'='video_task' THEN 'video' ELSE 'image' END,'title','bridge','body','','topics','[]'::jsonb,'media',jsonb_build_array(jsonb_build_object('id',media_id,'role',CASE WHEN reference->>'kind'='video_task' THEN 'video' ELSE 'image' END,'fileName',snapshot->'file'->'fileName','size',snapshot->'file'->'size','type',snapshot->'file'->'mime','lastModified',0,'source','main_asset','requiresReselection',false,'reference',reference)),'targets','[]'::jsonb);
 result:=public.mutate_native_core_atomic(actor,jsonb_build_object('action','save-native-draft','requestKey',prefix||':draft','requestHash',repeat('a',64),'connectionId',namespace,'save',jsonb_build_object('action','save-draft','base',jsonb_build_object('action','save-draft','expectedRevision',0,'draft',payload),'expectedMetadataRevision',0,'metadata',metadata),'mediaEntryRefs','[]'::jsonb));draft:=(result->'base'->'row'->>'id')::uuid;
 SELECT u.media_entry_id INTO entry_id FROM public.pub_native_media_usage_refs u WHERE u.owner_id=actor AND u.draft_id=draft AND u.draft_version=1 AND u.media_id=fixture.media_id;
 INSERT INTO public.pub3_auth_sessions(id,owner_id,connection_id,platform,request_key) VALUES(auth_id,actor,namespace,'douyin',prefix||':auth');INSERT INTO public.pub3_account_bindings(id,owner_id,connection_id,platform,provider_account_id,platform_uid,display_name,auth_session_id) VALUES(binding_id,actor,namespace,'douyin','synthetic.'||bridge_id::text,'synthetic.'||bridge_id::text,'synthetic ready bridge fixture',auth_id);
 intent:=jsonb_build_object('draftId',draft,'draftVersion',1,'bindingId',binding_id,'bindingRevision',1,'mediaIds',jsonb_build_array(media_id),'assetIds',jsonb_build_array(asset_id),'publishAt',NULL,'options','{}'::jsonb);
 result:=public.mutate_publish_v3_atomic(actor,jsonb_build_object('action','save-intent','connectionId',namespace,'expectedRevision',0,'payload',intent));PERFORM pg_temp.bridge_assert(result->'intent'->>'draft_id'=draft::text,'real V3 save intent accepts exact ready bridge');
 INSERT INTO public.pub3_operations(id,owner_id,kind,subject_id,connection_id,request_key,request_hash,snapshot,snapshot_hash,provider_request_hash,grant_kind,grant_subject,grant_used,dispatch_state,outcome,intent_revision) VALUES(gen_random_uuid(),actor,'publish',(result->'intent'->>'id')::uuid,namespace,prefix||':historical-publish',repeat('a',64),jsonb_build_object('draft',payload,'intent',intent,'binding',jsonb_build_object('id',binding_id,'revision',1),'assets',jsonb_build_array(proof)),repeat('b',64),repeat('c',64),'create_flow','synthetic.historical',true,'settled','published',1);
 facts:=public.native_core_media_usage_facts(actor,entry_id);PERFORM pg_temp.bridge_assert(facts->>'confirmedUses'='1' AND facts->>'unknownUses'='0' AND facts->>'nativeUsageAttribution'='entry_provenance','main entry official usage is confirmed only through ready exact bridge provenance');
 other_snapshot:=jsonb_set(jsonb_set(snapshot,'{mediaId}',to_jsonb(other_media)),'{file,fileName}',to_jsonb('native-bridge-'||other_bridge::text||CASE WHEN reference->>'kind'='video_task' THEN '.mp4' ELSE '.png' END));
 INSERT INTO public.pub3_assets(id,owner_id,connection_id,local_media_id,file_name,mime,size,sha256,request_key) VALUES(other_asset,actor,namespace,other_media,'ordinary.png','image/png',1,repeat('a',64),prefix||':ordinary');
 rejected:=false;BEGIN PERFORM public.mutate_native_media_bridge_atomic(actor,jsonb_build_object('action','prepare','requestKey',prefix||':ordinary-claim','currentNamespace',namespace,'bridgeId',other_bridge,'snapshot',other_snapshot,'snapshotHash',repeat('a',64)));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_MEDIA_RESERVED';END;PERFORM pg_temp.bridge_assert(rejected,'prepare never upgrades an existing ordinary pub3 upload into bridge proof');
 rejected:=false;BEGIN UPDATE public.pub_native_media_bridges b SET snapshot=jsonb_set(b.snapshot,'{file,size}','17') WHERE b.id=fixture.bridge_id;EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_HISTORY_IMMUTABLE';END;PERFORM pg_temp.bridge_assert(rejected,'bridge snapshot is immutable after prepare');
 rejected:=false;BEGIN UPDATE public.pub_native_media_bridge_phases ph SET dispatch_id=NULL WHERE ph.bridge_id=fixture.bridge_id AND ph.phase='sign';EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_BRIDGE_HISTORY_IMMUTABLE';END;PERFORM pg_temp.bridge_assert(rejected,'phase grant can never be reset or reissued');
 PERFORM pg_temp.bridge_assert(NOT has_table_privilege('service_role','public.pub_native_media_bridges','INSERT') AND NOT has_table_privilege('service_role','public.pub_native_media_bridge_phases','UPDATE') AND has_function_privilege('service_role','public.mutate_native_media_bridge_atomic(text,jsonb)','EXECUTE') AND NOT has_function_privilege('authenticated','public.mutate_native_media_bridge_atomic(text,jsonb)','EXECUTE') AND NOT has_function_privilege('service_role','public.native_media_source_fingerprint(text,jsonb)','EXECUTE'),'bridge has exact service-only RPC and read-only table ACL');
 PERFORM pg_temp.bridge_assert(before_wallet=(SELECT jsonb_build_object('credits',credits,'cash',cash_balance) FROM public.users WHERE id=actor),'bridge phases and synthetic receipts never debit a wallet');
END$$;
SELECT name,passed FROM native_bridge_fixture_results ORDER BY name;
